package org.jsoup.nodes;

import java.util.regex.Pattern;

class AttributeKeyUtil {
    static final Pattern xmlKeyReplace = Pattern.compile("[^-a-zA-Z0-9_:.]+");
    static final Pattern htmlKeyReplace = Pattern.compile("[\\x00-\\x1f\\x7f-\\x9f \"'/=]+");

    static boolean isValidXmlKey(String key) {
        final int length = key.length();
        if (length == 0) return false;
        char c = key.charAt(0);
        if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_' || c == ':'))
            return false;
        for (int i = 1; i < length; i++) {
            c = key.charAt(i);
            if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-' || c == '_' || c == ':' || c == '.'))
                return false;
        }
        return true;
    }

    static boolean isValidHtmlKey(String key) {
        final int length = key.length();
        if (length == 0) return false;
        for (int i = 0; i < length; i++) {
            char c = key.charAt(i);
            if ((c <= 0x1f) || (c >= 0x7f && c <= 0x9f) || c == ' ' || c == '"' || c == '\'' || c == '/' || c == '=')
                return false;
        }
        return true;
    }

    static String coerceXmlKey(String key) {
        key = xmlKeyReplace.matcher(key).replaceAll("_");
        return isValidXmlKey(key) ? key : null;
    }

    static String coerceHtmlKey(String key) {
        key = htmlKeyReplace.matcher(key).replaceAll("_");
        return isValidHtmlKey(key) ? key : null;
    }
}
